'use strict';
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const root=path.resolve(__dirname,'..'),previous=JSON.parse(fs.readFileSync(path.join(root,'docs/legacy-regression-validation-20261003.json'),'utf8')),commands=[...new Set(previous.results.map(r=>r.command))],results=[];
const output=path.join(root,'docs/legacy-regression-validation-20261003-r6.json'),logs=path.join(root,'docs/qa-regression-logs');fs.mkdirSync(logs,{recursive:true});
let next=0;async function worker(){while(next<commands.length){const index=next++,command=commands[index];await new Promise(resolve=>{const child=cp.spawn('bash',['-c',command],{cwd:root,env:process.env}),parts=[];child.stdout.on('data',x=>parts.push(x));child.stderr.on('data',x=>parts.push(x));child.on('close',exitCode=>{const status=exitCode===0?'passed':'failed';fs.writeFileSync(path.join(logs,String(index+1).padStart(2,'0')+'.txt'),Buffer.concat(parts));results[index]={command,exitCode,status};fs.writeFileSync(output,JSON.stringify({testedAt:new Date().toISOString(),scope:'All78 original unique regression commands, executed against R6 complete-text prompt and named horary rule files',results,passed:results.filter(r=>r&&r.status==='passed').length,total:commands.length},null,2));console.log(status.toUpperCase()+' '+(index+1)+'/'+commands.length+' '+command);resolve();});});}}
Promise.all(Array.from({length:Math.min(4,commands.length)},worker)).then(()=>{if(results.some(r=>r.status!=='passed'))process.exitCode=1;});
